INSERT INTO "brands" ("slug", "name", "english_name", "intro", "content", "color", "position") VALUES
('iran-khodro', 'ایران‌خودرو', 'Iran Khodro',
 'خرید اقساطی محصولات ایران‌خودرو مثل پژو ۲۰۷، تارا و دنا پلاس با پیش‌پرداخت کم و تحویل سریع.',
 '<h2>چرا خرید اقساطی ایران‌خودرو؟</h2><p>ایران‌خودرو بزرگ‌ترین خودروساز کشور است و قطعات و خدمات پس از فروش محصولاتش در همه شهرها در دسترس است. همین موضوع باعث می‌شود خودروهای این برند ارزش خود را در بازار خوب حفظ کنند و برای خرید اقساطی گزینه‌ای مطمئن باشند.</p><p>در خودرو قسطی می‌توانید محصولات ایران‌خودرو را بدون ضامن، فقط با چک صیادی و با بازپرداخت ۱۲ تا ۴۸ ماهه خریداری کنید.</p>',
 '#1d4ed8', 1),
('saipa', 'سایپا', 'Saipa',
 'خرید اقساطی خودروهای سایپا مثل شاهین و کوییک، صفر و کارکرده، بدون ضامن و با اقساط تا ۴۸ ماه.',
 '<h2>خرید اقساطی سایپا با پیش‌پرداخت کم</h2><p>محصولات سایپا به دلیل قیمت مناسب و هزینه نگهداری پایین، از پرطرفدارترین گزینه‌ها برای خرید اقساطی هستند. پیش‌پرداخت خودروهای سایپا از ۲۵ درصد قیمت شروع می‌شود.</p><p>علاوه بر خودروهای صفر، خودروهای کارکرده کارشناسی‌شده سایپا هم با شرایط اقساطی عرضه می‌شوند.</p>',
 '#0f766e', 2),
('modiran-khodro', 'مدیران‌خودرو', 'Modiran Khodro',
 'خرید اقساطی شاسی‌بلندها و سواری‌های مدیران‌خودرو با شرایط شفاف و پیش‌پرداخت مناسب.',
 '<h2>خرید اقساطی محصولات مدیران‌خودرو</h2><p>مدیران‌خودرو با محصولات ام‌وی‌ام، به‌ویژه شاسی‌بلندهای خانواده X، سهم بزرگی از بازار خودروهای مونتاژی دارد. این خودروها را می‌توانید با اقساط ثابت ماهانه و سند به نام خودتان خریداری کنید.</p>',
 '#b91c1c', 3),
('kerman-motor', 'کرمان موتور', 'Kerman Motor',
 'خرید اقساطی محصولات کرمان موتور با بازپرداخت منعطف و سند به نام خریدار از روز اول.',
 '<h2>خرید اقساطی کرمان موتور</h2><p>کرمان موتور با محصولات کی‌ام‌سی، از شاسی‌بلند تا وانت، گزینه‌های متنوعی برای خانواده‌ها و کسب‌وکارها دارد. شرایط اقساطی این برند با بازپرداخت منعطف و بدون نیاز به ضامن ارائه می‌شود.</p>',
 '#7c3aed', 4),
('fownix', 'فونیکس', 'Fownix',
 'خرید اقساطی خودروهای فونیکس، از سواری تا شاسی‌بلند، با تحویل فوری مدل‌های موجود.',
 '<h2>خرید اقساطی فونیکس با تحویل فوری</h2><p>فونیکس، برند محصولات چری در گروه مدیران‌خودرو، با خودروهایی مثل تیگو ۷ پرو و آریزو ۶ پرو شناخته می‌شود. مدل‌های موجود فونیکس با تحویل فوری و اقساط تا ۴۸ ماه عرضه می‌شوند.</p>',
 '#c2410c', 5),
('bahman-motor', 'بهمن موتور', 'Bahman Motor',
 'خرید اقساطی محصولات بهمن موتور با پیش‌پرداخت از ۳۰ درصد و اقساط ثابت ماهانه.',
 '<h2>خرید اقساطی بهمن موتور</h2><p>بهمن موتور با محصولات بسترن، از جمله فیدلیتی و دیگنیتی، در بازار شاسی‌بلندها و سواری‌های خانوادگی حضور دارد. این خودروها را با پیش‌پرداخت از ۳۰ درصد و اقساط ثابت ماهانه بخرید.</p>',
 '#0369a1', 6);
--> statement-breakpoint
INSERT INTO "cars" ("slug", "brand_id", "name", "year", "condition", "mileage", "price", "min_down_percent", "gearbox", "fuel", "color", "tags", "weekly_views", "position")
SELECT c.slug, b.id, c.name, c.year, c.condition::car_condition, c.mileage, c.price, c.down, c.gearbox, 'بنزین', c.color, c.tags, c.views, c.pos
FROM (VALUES
  ('peugeot-207-at', 'iran-khodro', 'پژو ۲۰۷ اتوماتیک', 1405, 'new', 0, 1450000000, 30, 'اتوماتیک', '#e5e7eb', ARRAY['تحویل فوری'], 18400, 1),
  ('tara-at', 'iran-khodro', 'تارا اتوماتیک', 1405, 'new', 0, 1650000000, 30, 'اتوماتیک', '#1e3a8a', ARRAY['پرفروش'], 15900, 2),
  ('dena-plus-turbo', 'iran-khodro', 'دنا پلاس توربو', 1405, 'new', 0, 1550000000, 30, 'اتوماتیک', '#111827', ARRAY['تحویل ۷ روزه'], 9800, 3),
  ('haima-s7-turbo', 'iran-khodro', 'هایما S7 توربو', 1404, 'used', 12000, 2400000000, 40, 'اتوماتیک', '#64748b', ARRAY['شاسی‌بلند'], 6100, 4),
  ('shahin-g', 'saipa', 'شاهین G', 1405, 'new', 0, 1100000000, 25, 'دستی', '#b91c1c', ARRAY['اقتصادی'], 13200, 1),
  ('saina-s', 'saipa', 'ساینا S', 1405, 'new', 0, 820000000, 25, 'دستی', '#f8fafc', ARRAY['اقتصادی'], 5400, 2),
  ('quick-r', 'saipa', 'کوییک R', 1403, 'used', 25000, 780000000, 35, 'دستی', '#f8fafc', ARRAY['کارشناسی‌شده'], 7300, 3),
  ('mvm-x55-pro', 'modiran-khodro', 'ام‌وی‌ام X55 پرو', 1405, 'new', 0, 2850000000, 35, 'اتوماتیک', '#f1f5f9', ARRAY['شاسی‌بلند'], 14700, 1),
  ('mvm-315-plus', 'modiran-khodro', 'ام‌وی‌ام ۳۱۵ پلاس', 1404, 'used', 18000, 1350000000, 35, 'دستی', '#0f172a', ARRAY['کارشناسی‌شده'], 4200, 2),
  ('kmc-j7', 'kerman-motor', 'کی‌ام‌سی J7', 1405, 'new', 0, 2650000000, 35, 'اتوماتیک', '#334155', ARRAY['شاسی‌بلند'], 11500, 1),
  ('kmc-t8', 'kerman-motor', 'کی‌ام‌سی T8', 1405, 'new', 0, 3900000000, 40, 'اتوماتیک', '#e2e8f0', ARRAY['وانت'], 3900, 2),
  ('tiggo-7-pro', 'fownix', 'تیگو ۷ پرو', 1405, 'new', 0, 3100000000, 40, 'اتوماتیک', '#7f1d1d', ARRAY['تحویل فوری'], 12800, 1),
  ('arrizo-6-pro', 'fownix', 'آریزو ۶ پرو', 1405, 'new', 0, 2200000000, 35, 'اتوماتیک', '#1e293b', ARRAY['سدان'], 6800, 2),
  ('fidelity-prime', 'bahman-motor', 'فیدلیتی پرایم', 1405, 'new', 0, 3400000000, 40, 'اتوماتیک', '#e2e8f0', ARRAY['۷ نفره'], 8900, 1),
  ('dignity-prestige', 'bahman-motor', 'دیگنیتی پرستیژ', 1405, 'new', 0, 3700000000, 40, 'اتوماتیک', '#111827', ARRAY['شاسی‌بلند'], 5100, 2)
) AS c(slug, brand, name, year, condition, mileage, price, down, gearbox, color, tags, views, pos)
JOIN "brands" b ON b.slug = c.brand;
